	<div class="alert alert-info" role="status"><strong><?php echo $this->escape($this->stage->project_name); ?></strong><span class="mx-2">/</span><?php echo $this->escape($this->stage->name); ?></div><?php echo LayoutHelper::render('joomla.searchtools.default', ['view' => $this]); ?>
	<div class="table-responsive"><table class="table table-striped" id="roundList"><thead><tr><td class="w-1 text-center"><?php echo HTMLHelper::_('grid.checkall'); ?></td><th class="w-1"><span class="visually-hidden"><?php echo Text::_('JACTION_EDIT'); ?></span></th><th class="text-center"><?php echo HTMLHelper::_('searchtools.sort', 'COM_JOOMLEAGUE_FIELD_ROUND_NUMBER_LABEL', 'a.sequence_number', $listDirn, $listOrder); ?></th><th><?php echo Text::_('COM_JOOMLEAGUE_FIELD_NAME_LABEL'); ?></th><th class="w-1"><span class="visually-hidden"><?php echo Text::_('COM_JOOMLEAGUE_ROUND_MATCHES_MANAGE'); ?></span></th><th><?php echo Text::_('COM_JOOMLEAGUE_FIELD_ROUND_TYPE_LABEL'); ?></th><th><?php echo Text::_('COM_JOOMLEAGUE_FIELD_DATE_RANGE_LABEL'); ?></th><th><?php echo Text::_('COM_JOOMLEAGUE_FIELD_LIFECYCLE_STATE_LABEL'); ?></th><th class="text-center"><?php echo Text::_('JSTATUS'); ?></th><th class="text-center"><?php echo HTMLHelper::_('searchtools.sort', 'JGRID_HEADING_ID', 'a.id', $listDirn, $listOrder); ?></th></tr></thead><tbody>
	<?php foreach ($this->items as $i => $item) : $canEdit = $user->authorise('core.edit', 'com_joomleague'); $canChange = $user->authorise('core.edit.state', 'com_joomleague'); $checkedOut = (int) $item->checked_out !== 0 && (int) $item->checked_out !== (int) $user->id; ?>
