	<?php endforeach; ?><?php if ($this->items === []) : ?><tr><td colspan="10"><div class="alert alert-warning mb-0"><?php echo Text::_('COM_JOOMLEAGUE_ROUNDS_EMPTY'); ?></div></td></tr><?php endif; ?></tbody></table></div><?php echo $this->pagination->getListFooter(); ?>
